#!/usr/bin/env python3
"""Resolve intact delta entries of a damaged pack using bases from an external git object store."""
import sys, re, zlib, hashlib, subprocess, os
sys.path.insert(0, '/tmp/tools')
packp, idxp, repo, outdir = sys.argv[1:5]
import importlib.util
spec = importlib.util.spec_from_file_location('pp', '/tmp/tools/packparse.py')
# reuse functions by exec of the module without running main
src = open('/tmp/tools/packparse.py').read().replace('\nmain()\n', '\n')
ns = {}
exec(compile(src, 'packparse', 'exec'), ns)
data = open(packp, 'rb').read()
entries, _ = ns['read_idx'](idxp)
byoff = {o: (s, c) for s, c, o in entries}
sha2off = {s: o for s, c, o in entries}
import binascii
raw = {}
for off, (sha, crc) in byoff.items():
    t, size, p = ns['parse_header'](data, off)
    base = None
    if t == 6:
        rel, p = ns['parse_ofs'](data, p); base = off - rel
    elif t == 7:
        base = data[p:p+20].hex(); p += 20
    payload, err, consumed = ns['inflate'](data, p, size)
    end = p + consumed
    crc_ok = err is None and (binascii.crc32(data[off:end]) & 0xffffffff) == crc
    raw[off] = dict(sha=sha, type=t, size=size, base=base, payload=payload, err=err, crc_ok=crc_ok)
def ext_get(sha):
    r = subprocess.run(['git', '--git-dir', repo, 'cat-file', '-t', sha], capture_output=True, text=True)
    if r.returncode != 0: return None, None
    t = r.stdout.strip()
    c = subprocess.run(['git', '--git-dir', repo, 'cat-file', t, sha], capture_output=True).stdout
    return t, c
resolved = {}
def resolve(off):
    if off in resolved: return resolved[off]
    e = raw[off]
    # prefer external copy if present (it's verified)
    t, c = ext_get(e['sha'])
    if t:
        resolved[off] = (t, c, None); return resolved[off]
    if not e['crc_ok']:
        resolved[off] = (None, None, 'corrupt'); return resolved[off]
    if e['type'] in (1,2,3,4):
        resolved[off] = (ns['TYPES'][e['type']], e['payload'], None); return resolved[off]
    boff = e['base'] if e['type'] == 6 else sha2off.get(e['base'])
    if boff is None:
        bt, bc = ext_get(e['base'])
        if not bt:
            resolved[off] = (None, None, 'missing refbase'); return resolved[off]
    else:
        bt, bc, berr = resolve(boff)
        if berr:
            resolved[off] = (None, None, 'base ' + berr); return resolved[off]
    try:
        content = ns['apply_delta'](bc, e['payload'])
    except Exception as ex:
        resolved[off] = (None, None, 'delta error %s' % ex); return resolved[off]
    resolved[off] = (bt, content, None); return resolved[off]
os.makedirs(outdir, exist_ok=True)
newly = []
for off in sorted(raw):
    e = raw[off]
    if ext_get(e['sha'])[0]: continue
    t, c, err = resolve(off)
    if err:
        print('UNRESOLVED', e['sha'], ns['TYPES'][e['type']], 'size', e['size'], 'crc_ok', e['crc_ok'], err)
        continue
    full = ('%s %d\0' % (t, len(c))).encode() + c
    h = hashlib.sha1(full).hexdigest()
    if h != e['sha']:
        print('HASH MISMATCH', e['sha'], h); continue
    open(os.path.join(outdir, e['sha']), 'wb').write(full)
    newly.append((e['sha'], t, len(c)))
print('newly resolved:', len(newly))
for n in newly: print(' ', n)
EOF
